#!/usr/bin/env python3
"""Extract the actual single C++20 article fence and run independent original-objective oracles."""
from pathlib import Path
import os
import shutil
import re
import subprocess
import sys
import tempfile

args = [arg for arg in sys.argv[1:] if arg != "--sanitize"]
article = Path(args[0]) if args else Path(__file__).resolve().parents[1] / "src/content/docs/techniques/median-ticket-extreme-selection-round-decomposition.mdx"
blocks = re.findall(r"^```cpp\s*\n(.*?)^```\s*$", article.read_text(), re.M | re.S)
if len(blocks) != 1:
    raise RuntimeError("expected exactly one complete C++ fence")
TESTS = '#include <chrono>\n#include <cstdlib>\n#include <functional>\n#include <iostream>\n#include <limits>\n#include <random>\n#include <string>\nusing I = std::int64_t;\nusing Matrix = std::vector<std::vector<I>>;\nstd::uint64_t checks = 0, oracle_allocations = 0, exhaustive_inputs = 0;\nstd::uint64_t checksum = 0;\nvoid require(bool condition, const std::string& message) {\n    ++checks;\n    if (!condition) { std::cerr << "FAIL: " << message << \'\\n\'; std::exit(1); }\n}\n// Directly minimize absolute deviations over each possible median value.\n// This oracle never separates values into positive and negative piles.\nI direct_round(const std::vector<I>& values) {\n    I best = std::numeric_limits<I>::max();\n    for (I center : values) {\n        I score = 0;\n        for (I value : values) score += value >= center ? value - center : center - value;\n        best = std::min(best, score);\n    }\n    return best;\n}\n// Enumerate every injective ordered k-tuple of ticket indices for each color,\n// then evaluate the original objective for every round of the full allocation.\nI direct_allocation(const Matrix& x, int k) {\n    const int n = static_cast<int>(x.size()), m = static_cast<int>(x[0].size());\n    std::vector<std::vector<I>> values(k, std::vector<I>(n));\n    I best = -1;\n    std::function<void(int)> choose_color;\n    choose_color = [&](int color) {\n        if (color == n) {\n            ++oracle_allocations;\n            I total = 0;\n            for (const auto& round : values) total += direct_round(round);\n            best = std::max(best, total);\n            return;\n        }\n        std::vector<bool> used(m, false);\n        std::function<void(int)> choose_round = [&](int round) {\n            if (round == k) { choose_color(color + 1); return; }\n            for (int j = 0; j < m; ++j) if (!used[j]) {\n                used[j] = true;\n                values[round][color] = x[color][j];\n                choose_round(round + 1);\n                used[j] = false;\n            }\n        };\n        choose_round(0);\n    };\n    choose_color(0);\n    return best;\n}\nI validate(const Matrix& x, int k, const MedianTicketAllocation& result, bool small) {\n    const int n = static_cast<int>(x.size()), m = static_cast<int>(x[0].size());\n    require(result.round_of_ticket.size() == x.size(), "returned color count");\n    std::vector<std::vector<I>> rounds(k);\n    for (auto& round : rounds) round.reserve(n);\n    for (int color = 0; color < n; ++color) {\n        require(result.round_of_ticket[color].size() == x[color].size(), "returned ticket count");\n        std::vector<int> seen(k, 0);\n        for (int j = 0; j < m; ++j) {\n            const int round = result.round_of_ticket[color][j];\n            require(round >= -1 && round < k, "valid unused marker or round index");\n            if (round != -1) {\n                ++seen[round];\n                rounds[round].push_back(x[color][j]);\n            }\n        }\n        for (int count : seen) require(count == 1, "every color occurs once in every round");\n    }\n    I total = 0;\n    for (auto& round : rounds) {\n        require(round.size() == static_cast<std::size_t>(n), "round color count");\n        if (small) total += direct_round(round);\n        else {\n            std::nth_element(round.begin(), round.begin() + n / 2, round.end());\n            const I median = round[n / 2];\n            for (I value : round) total += value >= median ? value - median : median - value;\n        }\n    }\n    require(total == result.score, "reported score equals actual minimum absolute-deviation sum");\n    checksum = checksum * 1000003 + static_cast<std::uint64_t>(result.score);\n    return total;\n}\nvoid compare(const Matrix& x, int k) {\n    const I expected = direct_allocation(x, k);\n    const auto result = maximize_median_ticket_deviation(x, k);\n    require(validate(x, k, result, true) == expected, "global optimum versus every original allocation");\n}\nstd::vector<std::vector<I>> sorted_rows(int m, int alphabet) {\n    std::vector<std::vector<I>> result;\n    std::vector<I> row(m);\n    std::function<void(int,int)> generate = [&](int pos, int low) {\n        if (pos == m) { result.push_back(row); return; }\n        for (int value = low; value < alphabet; ++value) {\n            row[pos] = value;\n            generate(pos + 1, value);\n        }\n    };\n    generate(0, 0);\n    return result;\n}\nvoid exhaustive(int n, int m, int alphabet) {\n    const auto rows = sorted_rows(m, alphabet);\n    Matrix x(n);\n    std::function<void(int)> generate = [&](int color) {\n        if (color == n) {\n            for (int k = 1; k <= m; ++k) { ++exhaustive_inputs; compare(x, k); }\n            return;\n        }\n        for (const auto& row : rows) { x[color] = row; generate(color + 1); }\n    };\n    generate(0);\n}\nvoid reject(const Matrix& values, int k) {\n    bool threw = false;\n    try { (void)maximize_median_ticket_deviation(values, k); }\n    catch (const std::invalid_argument&) { threw = true; }\n    require(threw, "invalid API input is rejected");\n}\nint main() {\n    const auto started = std::chrono::steady_clock::now();\n    // Independently verify that testing centers at selected values gives the\n    // literal minimum over all integer centers for every tiny ordered sequence.\n    for (int n : {2,4,6}) {\n        std::vector<I> row(n);\n        std::function<void(int)> generate = [&](int pos) {\n            if (pos < n) {\n                for (I value = 0; value <= 2; ++value) { row[pos] = value; generate(pos + 1); }\n                return;\n            }\n            I best = std::numeric_limits<I>::max();\n            for (I center = -1; center <= 3; ++center) {\n                I score = 0;\n                for (I value : row) score += value >= center ? value - center : center - value;\n                best = std::min(best, score);\n            }\n            require(direct_round(row) == best, "oracle versus literal integer centers");\n        };\n        generate(0);\n    }\n    for (int m = 1; m <= 4; ++m) exhaustive(2, m, 3);\n    for (int m = 1; m <= 2; ++m) exhaustive(4, m, 3);\n    exhaustive(4, 3, 2);\n    for (int m = 1; m <= 2; ++m) exhaustive(6, m, 2);\n    require(exhaustive_inputs == 6244, "complete tiny matrix enumeration count");\n    const Matrix sample1{{0,2,5},{1,1,3}};\n    const Matrix sample2{{5,9},{1,4},{3,6},{2,7}};\n    require(validate(sample1,2,maximize_median_ticket_deviation(sample1,2),true) == 7, "official example 1");\n    require(validate(sample2,1,maximize_median_ticket_deviation(sample2,1),true) == 12, "official example 2");\n    std::mt19937 rng(20200916);\n    for (int trial = 0; trial < 512; ++trial) {\n        const int n = 2 + 2 * static_cast<int>(rng() % 2);\n        const int m = 1 + static_cast<int>(rng() % 3), k = 1 + static_cast<int>(rng() % m);\n        Matrix x(n, std::vector<I>(m));\n        for (auto& row : x) {\n            for (I& value : row) value = rng() % 13;\n            std::sort(row.begin(), row.end());\n        }\n        const Matrix saved = x;\n        compare(x,k);\n        require(x == saved, "input remains unchanged");\n        const I score = maximize_median_ticket_deviation(x,k).score;\n        std::reverse(x.begin(),x.end());\n        require(validate(x,k,maximize_median_ticket_deviation(x,k),true) == score, "color permutation invariance");\n        for (auto& row : x) for (I& value : row) value += 999999980;\n        require(validate(x,k,maximize_median_ticket_deviation(x,k),true) == score, "large uniform translation invariance");\n    }\n    // Full dimensions, maximum value and a score far outside 32-bit range.\n    Matrix maximum(1500,std::vector<I>(1500,1000000000LL));\n    for (int color = 0; color < 750; ++color)\n        std::fill(maximum[color].begin(),maximum[color].end(),0);\n    const I full_score = 1125000000000000LL;\n    require(validate(maximum,1500,maximize_median_ticket_deviation(maximum,1500),false) == full_score,\n        "maximum N/M/K with forced low and high colors");\n    require(validate(maximum,1,maximize_median_ticket_deviation(maximum,1),false) == 750000000000LL,\n        "maximum dimensions with K=1");\n    for (auto& row : maximum) {\n        std::fill(row.begin(),row.begin()+750,0);\n        std::fill(row.begin()+750,row.end(),1000000000LL);\n    }\n    require(validate(maximum,1500,maximize_median_ticket_deviation(maximum,1500),false) == full_score,\n        "maximum tie-heavy balanced extreme selection");\n    require(validate(maximum,1499,maximize_median_ticket_deviation(maximum,1499),false) == 1124250000000000LL,\n        "maximum near-full K");\n    for (auto& row : maximum) std::fill(row.begin(),row.end(),1000000000LL);\n    require(validate(maximum,1500,maximize_median_ticket_deviation(maximum,1500),false) == 0,\n        "all values equal: cancellation of 2.25e15 intermediates");\n    reject({},1);reject({{0}},1);reject({{0},{0},{0}},1);reject(Matrix(1502,{0}),1);\n    reject({{},{}},1);reject(Matrix(2,std::vector<I>(1501,0)),1);\n    reject({{0},{0,0}},1);reject({{0},{}},1);\n    reject({{0},{0}},0);reject({{0},{0}},-1);reject({{0},{0}},2);\n    reject({{0},{0}},std::numeric_limits<int>::max());\n    reject({{-1},{0}},1);reject({{0},{1000000001LL}},1);\n    reject({{2,1},{0,0}},1);\n    reject({{std::numeric_limits<I>::min()},{0}},1);\n    reject({{0},{std::numeric_limits<I>::max()}},1);\n    const double seconds = std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count();\n    std::cout << "Tickets C++20: " << checks << " checks passed; " << exhaustive_inputs\n              << " exhaustive matrices/K; " << oracle_allocations << " original allocations; checksum "\n              << checksum << "; " << seconds << "s\\n";\n}\n'

with tempfile.TemporaryDirectory(prefix="flowchartcp-tickets-") as directory:
    source = Path(directory) / "check.cpp"
    executable = Path(directory) / "check"
    source.write_text(blocks[0] + "\n" + TESTS)
    flags = ["-std=c++20", "-O2", "-Wall", "-Wextra", "-Werror"]
    environment = os.environ.copy()
    if "--sanitize" in sys.argv:
        flags += ["-g", "-fsanitize=address,undefined", "-fno-omit-frame-pointer"]
        environment["ASAN_OPTIONS"] = "detect_leaks=0"
    compiler = os.environ.get("CXX") or shutil.which("g++") or shutil.which("clang++") or "c++"
    subprocess.run([compiler, *flags, str(source), "-o", str(executable)], check=True, timeout=120)
    subprocess.run([str(executable)], check=True, env=environment, timeout=180)
